  data() { return {
    page:'search', tabs:[{id:'search',label:'강의 검색'},{id:'mine',label:'내 페이지'},{id:'session',label:'매칭 세션'}], courses:demoCourses, selectedCourse:null, keyword:'', appliedKeyword:'', wishIds:['GEN101','CSE330','CSE340','CSE201'], filters:{department:'전체',year:'전체',type:'전체',professor:'전체',day:'전체',time:'전체'}, onlyPossible:true,
    pairRows:[{wants:'프로그래밍언어론 01',code:'CSE210',competitors:2,holders:1,rank:'1위 / 2명',status:'매칭 중',possible:true},{wants:'컴파일러 01',code:'CSE322',competitors:1,holders:0,rank:'없음 · 시간 겹침',status:'반대쪽 없음',possible:false}],
    ownedCourses:[{code:'CSE210',name:'프로그래밍언어론',section:'01',time:'화목 15:00–16:15',credits:3},{code:'CSE322',name:'컴파일러',section:'01',time:'월수 12:00–13:15',credits:3},{code:'CSE330',name:'데이터베이스',section:'01',time:'화목 09:00–10:15',credits:3},{code:'CSE340',name:'운영체제',section:'02',time:'월수 13:30–14:45',credits:3}], selectedPairs:[], myPairs:[], ownedFilter:'전체',statusFilter:'전체',showUpload:false,upload:{code:'',name:'',section:'01',professor:'',time:'',credits:3},uploadedCourses:[],sessionStep:1,activePair:null,otherAccepted:false,completedAt:'',history:[],countdownSeconds:300,countdownTimer:null
  }; },
  computed:{
    enrolledCourses(){return this.courseList || [];},
    filteredCourses(){return this.courses.filter(c=>{const k=this.appliedKeyword.toLowerCase();return (!k||(c.name+' '+c.code).toLowerCase().indexOf(k)!==-1)&&(this.filters.department==='전체'||c.department===this.filters.department)&&(this.filters.year==='전체'||c.year===this.filters.year)&&(this.filters.type==='전체'||c.type===this.filters.type)&&(this.filters.professor==='전체'||c.professor===this.filters.professor)&&(this.filters.day==='전체'||c.time.indexOf(this.filters.day)!==-1)&&(this.filters.time==='전체'||(this.filters.time==='오전'?/09:|10:|11:|12:/.test(c.time):/13:|14:|15:|16:|17:/.test(c.time)));});},
    wishedCourses(){return this.courses.filter(c=>this.wishIds.indexOf(c.code)!==-1);},
    possiblePairs(){return this.pairRows.filter(p=>p.possible);},
    shownPairs(){return this.onlyPossible?this.possiblePairs:this.pairRows;},
    filteredMyPairs(){return this.myPairs.filter(p=>(this.ownedFilter==='전체'||p.ownedName.indexOf(this.ownedFilter)!==-1)&&(this.statusFilter==='전체'||p.status===this.statusFilter));},
    countdownDisplay(){const m=Math.floor(this.countdownSeconds/60);const s=this.countdownSeconds%60;return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
  },
  beforeDestroy(){if(this.countdownTimer)clearInterval(this.countdownTimer);},
  methods:{
    searchCourses(){this.appliedKeyword=this.keyword.trim();}, openCourse(course){this.selectedCourse=course;this.page='detail';}, toggleWish(course){const i=this.wishIds.indexOf(course.code);if(i===-1)this.wishIds.push(course.code);else this.wishIds.splice(i,1);}, isMine(code){return this.ownedCourses.concat(this.uploadedCourses).some(c=>c.code===code);},
    pairAllowed(wanted,owned){return wanted.code!==owned.code && wanted.time!==owned.time;}, pairKey(wanted,owned){return owned.code+'-'+wanted.code;}, isPairSelected(wanted,owned){return this.selectedPairs.some(p=>p.key===this.pairKey(wanted,owned));}, togglePair(wanted,owned){const key=this.pairKey(wanted,owned);const i=this.selectedPairs.findIndex(p=>p.key===key);if(i!==-1)this.selectedPairs.splice(i,1);else this.selectedPairs.push({key,ownedName:owned.name+' '+owned.section,wantedName:wanted.name+' '+wanted.section,ownedCode:owned.code,wantedCode:wanted.code,priority:this.wishedCourses.findIndex(c=>c.code===wanted.code)+1,status:'대기',rank:'1위 / 3명',opposite:'1명',note:'반대쪽에 사람이 오면 매칭',});},
    moveWish(index,delta){const arr=this.wishedCourses;const target=index+delta;if(target<0||target>=arr.length)return;const a=arr[index].code,b=arr[target].code;this.wishIds.splice(this.wishIds.indexOf(a),1);this.wishIds.splice(this.wishIds.indexOf(b),0,a);},
    startMatching(){if(!this.selectedPairs.length)return;this.myPairs=this.selectedPairs.map(p=>Object.assign({},p,{status:'대기',note:'반대쪽에 사람이 오면 매칭'}));this.myPairs[0].status='매칭 중';this.myPairs[0].note='최종 확정 대기 · 05:00';this.activePair=this.myPairs[0];this.sessionStep=1;this.page='session';}, openSession(pair){this.activePair=pair;this.sessionStep=pair.status==='교환 완료'?3:1;this.page='session';}, startCountdown(){if(this.countdownTimer)clearInterval(this.countdownTimer);this.countdownSeconds=300;this.countdownTimer=setInterval(()=>{if(this.sessionStep!==2){clearInterval(this.countdownTimer);this.countdownTimer=null;return;}if(this.countdownSeconds>0)this.countdownSeconds--;if(this.countdownSeconds<=0){clearInterval(this.countdownTimer);this.countdownTimer=null;this.cancelExpiredSession();}},1000);}, cancelExpiredSession(){this.sessionStep=0;if(this.activePair){this.activePair.status='대기';this.activePair.note='자동 취소 · 5분 내 확정되지 않음';}this.otherAccepted=false;}, rejectSession(){if(this.countdownTimer)clearInterval(this.countdownTimer);this.countdownTimer=null;this.sessionStep=0;if(this.activePair){this.activePair.status='대기';this.activePair.note='거절됨 · 다른 상대 대기 중';} }, completeExchange(){if(this.countdownTimer)clearInterval(this.countdownTimer);this.countdownTimer=null;this.sessionStep=3;this.completedAt=new Date().toLocaleString('ko-KR',{hour12:false});if(this.activePair){this.activePair.status='교환 완료';this.activePair.note='완료 · '+this.completedAt;this.history.unshift({date:this.completedAt,from:this.activePair.ownedName,to:this.activePair.wantedName});}
      // 실제 백엔드 연동 시 이 위치에서 교환 트랜잭션을 확정하고 수강신청내역 API를 갱신합니다.
      // await api.exchange.confirm({sessionId, acceptedByRequester: true, acceptedByHolder: true});
      // await api.enrollments.refresh();
      if (this.activePair) {
        const wantedCourse = this.courses.find(c => c.code === this.activePair.wantedCode) || this.courses.find(c => c.name === this.activePair.wantedName.replace(/ \d+$/, ''));
        const ownedCourse = this.ownedCourses.find(c => c.code === this.activePair.ownedCode);
        if (ownedCourse) this.ownedCourses = this.ownedCourses.filter(c => c.code !== ownedCourse.code);
        if (wantedCourse) {
          this.$emit('exchangeComplete', { ownedCode: this.activePair.ownedCode, ownedCourse, receivedCourse: wantedCourse });
        }
      }
    }, statusClass(status){return status==='매칭 중'?'status-matching':status==='교환 완료'?'status-done':status==='잠김'?'status-locked':'status-waiting';},
    uploadCourse(){if(this.courses.some(c=>c.code===this.upload.code)||this.uploadedCourses.some(c=>c.code===this.upload.code)){alert('이미 등록된 학수번호입니다.');return;}const c=Object.assign({type:'전공선택',capacity:40,wishers:0,holders:1,department:'컴퓨터공학과',year:'3학년'},this.upload,{section:String(this.upload.section)});this.uploadedCourses.push(c);this.ownedCourses.push(c);this.courses.push(c);this.upload={code:'',name:'',section:'01',professor:'',time:'',credits:3};this.showUpload=false;},removeUploaded(code){this.uploadedCourses=this.uploadedCourses.filter(c=>c.code!==code);this.ownedCourses=this.ownedCourses.filter(c=>c.code!==code);this.courses=this.courses.filter(c=>c.code!==code);}
  }
};
